static struct { uint32_t frames; int32_t wheel[2]; } fm1_in;
static int clamp(int v,int lo,int hi) { return v<lo?lo:v>hi?hi:v; }
#include "smk_wheels.inc"
static int32_t peak_sample;
static uint64_t hash=1469598103934665603ULL;
static void render(void) {
    int32_t out[512]; engine_render(out,256);
    for (unsigned i=0;i<512;i++) { if(out[i]>peak_sample) peak_sample=out[i]; hash^=(uint32_t)out[i]; hash*=1099511628211ULL; }
}
static void select_part(int part,int smc_path) {
    if(smc_path) {
        /* Source-strip SELECT notes 24..28 are momentary FX (owner hold-FX
         * buses), not part navigation — same as smc_reachability. Use the
         * production SMC part selector that REC / bank-channel still call. */
        smc_select_part(part);
        smc_poll(); smc_frame();
        assert(ui.part==part);
    } else { bass_step_cancel(); drum_step_cancel(); ui.part=(uint8_t)part; build_pages(); }
}
int main(int argc,char **argv) {
    assert(argc==7);
    int nav=atoi(argv[1]), playing=atoi(argv[2]), locks=atoi(argv[3]), smc_path=atoi(argv[4]), part=atoi(argv[5]), gesture=atoi(argv[6]);
    boot(); engine_guard_enable(0); render();
    for(int p=0;p<2;p++) {
        proj.sound.v[T_303][p][BASS303_CUTOFF]=30+p*10;
        engine_set(T_303,p,BASS303_CUTOFF,30+p*10);
    }
    if(smc_path) { proj.set.bt=PROJ_BT_SMC_CENTRAL; smc_ble_link(1); smc_poll(); smc_frame(); }
    select_part(PART_303A+part,smc_path); set_view(V_PART);
    fm1_in.frames=400; fm1_in.wheel[0]=550; fm1_in.wheel[1]=615; smk_wheels(); render();
    /* An intentional mod gesture; saved/displayed base remains 30/40. */
    fm1_in.wheel[1]=(gesture&1)?550:615;
    fm1_in.wheel[0]=(gesture&2)?580:550; smk_wheels(); render();
    /* 550 is up from the down end at 615: the wheel replaces the knob (57), it does not add. */
    if(gesture&1) {
        assert(last_target==T_303 && last_param==BASS303_CUTOFF && last_value==57);
        assert(observed_bass[part]->pot[BASS303_CUTOFF]==57);
    }
    if(locks) {
        int k=motion_alloc(proj.arr.lane,0,PART_303A+part,T_303,part,BASS303_CUTOFF);
        assert(k>=0);
        for(int i=0;i<NSTEPS;i++) proj.arr.lane[k].val[i]=(locks==2 && (i&1))?95:77;
        engine_motion_reset();
    }
    seq.mute=seq.vmute=0;
    bpart_t *bp=&proj.pat[0].bass[part]; bp->len=4;
    for(int i=0;i<4;i++) bp->step[i]=(bstep_t){48,G_NOTE,100};
    if(playing) { seq_start(&seq); render(); }
    else { engine_bass_on(part,48,0,0); render(); }
    unsigned before=commands;
    int cutoff=observed_bass[part]->pot[BASS303_CUTOFF];
    for(int i=0;i<160;i++) {
        /* Both leaving a 303 and selecting the other 303 must be silent routing changes. */
        if(nav && i==5) select_part(PART_909,smc_path);
        if(nav && i==15) select_part(PART_303A+(1-part),smc_path);
        if(nav && i==25) select_part(PART_303A+part,smc_path);
        if(nav && i==35) set_view(V_SEQ);
        if(nav && i==45) set_view(V_PART);
        smk_wheels();
        if(commands!=before) fprintf(stderr,"navigation scan=%d queued target=%d voice=%d param=%d value=%d; stored=%d DSP=%d\n",i,last_target,last_voice,last_param,last_value,proj.sound.v[T_303][part][BASS303_CUTOFF],observed_bass[part]->pot[BASS303_CUTOFF]);
        if(commands!=before) {
            render();
            fprintf(stderr,"after queue drain: DSP cutoff=%d hz=%.9g stored/displayed=%d\n",
                observed_bass[part]->pot[BASS303_CUTOFF],observed_bass[part]->cutoff,
                pref_get(PR(R_ENG,T_303,part,BASS303_CUTOFF)));
        }
        assert(commands==before); /* no queue write even before the next render */
        render();
        if(locks!=2 || !playing) assert(observed_bass[part]->pot[BASS303_CUTOFF]==cutoff);
        hash^=observed_bass[part]->pot[BASS303_CUTOFF]; hash*=1099511628211ULL;
        assert(pref_get(PR(R_ENG,T_303,part,BASS303_CUTOFF))==30+part*10);
        assert(proj.sound.v[T_303][part][BASS303_CUTOFF]==30+part*10);
    }
    assert(peak_sample>0);
    printf("audio=%016llx cutoff=%d hz=%.9g base=%d commands=%u\n",
        (unsigned long long)hash,cutoff,observed_bass[part]->cutoff,
        proj.sound.v[T_303][part][BASS303_CUTOFF],commands-before);
    /* Release offscreen still goes to gesture owner, never current screen. */
    select_part(PART_909,smc_path);
    fm1_in.wheel[1]=615; fm1_in.wheel[0]=550; smk_wheels();
    assert(commands==before+((gesture&1)!=0)+((gesture&2)!=0)); render();
    /* Down closes. The saved knob stays. The filter is not left open. */
    if((gesture&1) && !playing) assert(observed_bass[part]->pot[BASS303_CUTOFF]==0);
    /* A knob edit is authoritative while a stationary wheel is still held. */
    seq_stop(&seq); render();
    select_part(PART_303A+part,smc_path);
    fm1_in.wheel[1]=550; smk_wheels(); render();
    proj.sound.v[T_303][part][BASS303_CUTOFF]=51;
    engine_set(T_303,part,BASS303_CUTOFF,51); render();
    before=commands;
    select_part(PART_909,smc_path); smk_wheels(); render();
    select_part(PART_303A+part,smc_path); smk_wheels(); render();
    assert(commands==before && observed_bass[part]->pot[BASS303_CUTOFF]==51);
    fm1_in.wheel[1]=615; smk_wheels(); render();
    /* Simultaneous gestures retain independent targets across part changes. */
    fm1_in.wheel[1]=550; smk_wheels(); render();
    select_part(PART_303A+(1-part),smc_path);
    fm1_in.wheel[0]=580; smk_wheels(); render();
    assert(last_param==CHI_PBEND && last_voice==1-part && last_value!=64);
    assert(observed_bass[1-part]->pot[BASS303_TUNE]==64);
    assert(observed_bass[1-part]->bend_pot==(uint8_t)last_value);
    before=commands;
    fm1_in.wheel[1]=615; smk_wheels();
    assert(commands==before+1 && last_voice==part && last_param==BASS303_CUTOFF && last_value==0);
    fm1_in.wheel[0]=550; smk_wheels();
    assert(commands==before+2 && last_voice==1-part && last_param==CHI_PBEND);
    assert(last_value==proj.sound.v[T_303][1-part][CHI_PBEND]);
    render();
    assert(observed_bass[1-part]->pot[BASS303_TUNE]==64);
    assert(observed_bass[1-part]->bend_pot==proj.sound.v[T_303][1-part][CHI_PBEND]);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * Host test of the clip colour tables and the APC channel states.
 * tests/run_tests.sh first runs tools/apc_pad_colors.py into build/host (apc40_pad_default_gen.h,
 * apc40_lcd565_gen.h). The test compares them with the committed headers, so the tables and
 * the tool cannot drift. tests/apc_palette_test.py checks the colour rules. */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#define APC40_LCD565 APC40_LCD565_GEN
#include "apc40_lcd565_gen.h"
#undef APC40_LCD565
#define APC40_PAD_DEFAULT APC40_PAD_DEFAULT_GEN
#include "apc40_pad_default_gen.h"
#undef APC40_PAD_DEFAULT
#define PAD_GAMMA_LUT PAD_GAMMA_LUT_GEN
#define PAD_GAIN_Q8 PAD_GAIN_Q8_GEN
#include "apc40_pad_gamma_gen.h"
static const unsigned PAD_FLOOR_LEVEL_GEN = PAD_FLOOR_LEVEL;
#undef PAD_GAMMA_LUT
#undef PAD_GAIN_Q8
#undef PAD_FLOOR_LEVEL
#include "app/apc40_pad_gamma.h"
#include "app/apc40_lcd565.h"
#include "app/apc40_pad_default.h"
#include "app/smk_apc40.h"

static void test_sizes(void)
{
    assert(sizeof APC40_LCD565 == 256u);   /* 128 x RGB565 */
    assert(sizeof APC40_PAD_DEFAULT == 384u);      /* 128 x R, G, B: the calibration start point */
}

static void test_tool_makes_the_same_tables(void)
{
    unsigned i, bad = 0u;
    for (i = 0u; i < 128u; i++) {
        if (APC40_LCD565[i] != APC40_LCD565_GEN[i] || memcmp(APC40_PAD_DEFAULT[i], APC40_PAD_DEFAULT_GEN[i], 3u)) {
            printf("velocity %u: LCD 0x%04X tool 0x%04X, pad %u,%u,%u tool %u,%u,%u\n", i, APC40_LCD565[i],
                   APC40_LCD565_GEN[i], APC40_PAD_DEFAULT[i][0], APC40_PAD_DEFAULT[i][1], APC40_PAD_DEFAULT[i][2],
                   APC40_PAD_DEFAULT_GEN[i][0], APC40_PAD_DEFAULT_GEN[i][1], APC40_PAD_DEFAULT_GEN[i][2]);
            bad++;
        }
    }
    fflush(stdout);
    assert(bad == 0u);
    assert(!memcmp(PAD_GAMMA_LUT, PAD_GAMMA_LUT_GEN, sizeof PAD_GAMMA_LUT));
    assert(!memcmp(PAD_GAIN_Q8, PAD_GAIN_Q8_GEN, sizeof PAD_GAIN_Q8) && PAD_FLOOR_LEVEL == PAD_FLOOR_LEVEL_GEN);
}

/* The same lookups as main_fm1.c (tests/smk_apc40_test.py checks the firmware text). */
static uint16_t lcd_colour(uint8_t v) { return APC40_LCD565[v & 0x7Fu]; }
static uint8_t pad_send(uint8_t v, unsigned ch, uint8_t brightness)
{
    return (uint8_t)(APC40_PAD_DEFAULT[v][ch] * brightness / 510u);
}

static void test_lit_and_empty(void)
{
    unsigned v;
    assert(lcd_colour(0u) == 0u && !(APC40_PAD_DEFAULT[0][0] | APC40_PAD_DEFAULT[0][1] | APC40_PAD_DEFAULT[0][2]));    /* empty cell: dim dot, pad dark */
    for (v = 1u; v < 128u; v++) {
        uint8_t mx = 0u, s;
        assert(lcd_colour((uint8_t)v) != 0u);               /* a lit cell is not black */
        for (s = 0u; s < 3u; s++) {
            uint8_t c = pad_send((uint8_t)v, s, 255u);
            if (c > mx)
                mx = c;
        }
        assert(mx >= 2u);                                   /* the pad floor of the start point: dim entries show */
    }
    for (v = 128u; v < 256u; v++)                           /* > 127 stays in the table */
        assert(lcd_colour((uint8_t)v) == APC40_LCD565[v - 128u]);
}

static void test_channel_states(void)
{
    /* Protocol v1.2 "RGB LEDs Type": channel 0 primary (solid), 1-5 one-shot, 6-10 pulsing,
     * 11-15 blinking, at 1/24, 1/16, 1/8, 1/4, 1/2 (MIDI clock 4, 6, 12, 24, 48 ticks). */
    static const uint8_t ticks[5] = {4u, 6u, 12u, 24u, 48u};
    uint8_t ch;
    for (ch = 0u; ch < 16u; ch++) {
        uint8_t blink = smk_apc40_is_queued(ch);
        assert(blink == (ch >= 11u));                       /* only the blinking states blink */
        if (ch < 6u)
            assert(smk_apc40_animation_clock_period(ch) == 0u);
        else
            assert(smk_apc40_animation_clock_period(ch) == ticks[(ch - 6u) % 5u]);
        /* Solid, one-shot and pulsing draw steady at full level. Blinking is on, then off. */
        assert(smk_apc40_brightness(ch, 0u, 0u) == 255u);
        assert(smk_apc40_brightness(ch, 200u, 0u) == (blink ? 0u : 255u));
    }
    /* The channel does not change the colour: the cell stores the velocity and the channel. */
    {
        volatile uint8_t vel[SMK_APC40_CLIP_COUNT] = {0}, chan[SMK_APC40_CLIP_COUNT] = {0};
        assert(smk_apc40_feedback_set(vel, chan, 5u, 13u, 81u) && vel[5] == 81u && chan[5] == 13u);
        assert(smk_apc40_feedback_set(vel, chan, 5u, 0x1Du, 0xD1u) && vel[5] == 0x51u && chan[5] == 13u);
        assert(!smk_apc40_feedback_set(vel, chan, SMK_APC40_CLIP_COUNT, 0u, 1u));
    }
}

int main(void)
{
    test_sizes();
    test_lit_and_empty();
    test_channel_states();
    test_tool_makes_the_same_tables();
    printf("apc40_tables_test: ok\n");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Drum voice pans (X0X): every voice centred, drum909_render_st / drum808_render_st give both sides
 * exactly the mono render's dry (and the same sends); a voice panned hard left leaves the right empty. */
#include <stdio.h>
#include <string.h>
#include "drum909.h"
#include "drum808.h"

#define N 256
static int fails;
static void check(int ok, const char *what)
{
    printf("  %s %s\n", ok ? "ok  " : "FAIL", what);
    fails += !ok;
}
static drum909_t a9, b9;
static drum808_t a8, b8;

int main(void)
{
    static float d[N], r[N], y[N], l[N], rr[N], r2[N], y2[N];
    int b, i, v, same = 1, quiet = 1, loud = 0;
    drum909_init(&a9);
    drum909_init(&b9);
    for (b = 0; b < 300; b++) {
        if (b % 25 == 0)
            for (v = 0; v < DR_NUM; v++) {
                drum909_trigger(&a9, v, 1.0f);
                drum909_trigger(&b9, v, 1.0f);
            }
        memset(d, 0, sizeof d); memset(r, 0, sizeof r); memset(y, 0, sizeof y);
        memset(l, 0, sizeof l); memset(rr, 0, sizeof rr); memset(r2, 0, sizeof r2); memset(y2, 0, sizeof y2);
        drum909_render(&a9, d, r, y, N);
        drum909_render_st(&b9, l, rr, r2, y2, N);
        same &= !memcmp(d, l, sizeof d) && !memcmp(d, rr, sizeof d) && !memcmp(r, r2, sizeof r) && !memcmp(y, y2, sizeof y);
    }
    check(same, "909: every voice centred: stereo == mono, bit for bit");
    drum808_init(&a8);
    drum808_init(&b8);
    same = 1;
    for (b = 0; b < 300; b++) {
        if (b % 25 == 0)
            for (v = 0; v < D8_NUM; v++) {
                drum808_trigger(&a8, v, 1.0f);
                drum808_trigger(&b8, v, 1.0f);
            }
        memset(d, 0, sizeof d); memset(r, 0, sizeof r); memset(y, 0, sizeof y);
        memset(l, 0, sizeof l); memset(rr, 0, sizeof rr); memset(r2, 0, sizeof r2); memset(y2, 0, sizeof y2);
        drum808_render(&a8, d, r, y, N);
        drum808_render_st(&b8, l, rr, r2, y2, N);
        same &= !memcmp(d, l, sizeof d) && !memcmp(d, rr, sizeof d) && !memcmp(r, r2, sizeof r) && !memcmp(y, y2, sizeof y);
    }
    check(same, "808: every track centred: stereo == mono, bit for bit");
    /* hard left: the snare (909) and the clap (808), the right stays empty */
    drum909_init(&b9);
    drum909_set(&b9, DR_SD, drum909_nparams(DR_SD) - 1, 0);
    drum808_init(&b8);
    drum808_set(&b8, D8_CP, drum808_nparams(D8_CP) - 1, 0);
    drum909_pan_settle(&b9);                         /* as the engine does while the kit is silent */
    drum808_pan_settle(&b8);
    for (b = 0; b < 40; b++) {
        if (b == 0) {
            drum909_trigger(&b9, DR_SD, 1.0f);
            drum808_trigger(&b8, D8_CP, 1.0f);
        }
        memset(l, 0, sizeof l); memset(rr, 0, sizeof rr); memset(r2, 0, sizeof r2); memset(y2, 0, sizeof y2);
        drum909_render_st(&b9, l, rr, r2, y2, N);
        drum808_render_st(&b8, l, rr, r2, y2, N);
        for (i = 0; i < N; i++) {
            quiet &= rr[i] == 0.0f;
            loud |= l[i] > 0.01f || l[i] < -0.01f;
        }
    }
    check(quiet && loud, "pan hard left: all on the left, nothing on the right");
    printf(fails ? "drum pan: %d FAILED\n" : "drum pan: ok\n", fails);
    return fails != 0;
}

#!/usr/bin/env python3
"""Check production SMC home routing and master mute feedback independently."""
import os
from pathlib import Path
import re
import subprocess
import tempfile

root = Path(__file__).resolve().parents[2]
source = Path(os.environ.get("SMC_SOURCE", root / "firmware/src/app/smc_mixer.c")).read_text()
functions = []
for name in ("smc_home_target", "smc_drum_mix", "smc_drum_track", "smc_lock_blocks", "smc_led"):
    match = re.search(r"^static [^\n]+ " + name + r"\([^\n]*\)\n\{.*?^\}", source, re.M | re.S)
    if name in ("smc_drum_mix", "smc_drum_track") and not match:
        continue
    assert match, name
    functions.append(match[0])
ui_source = (root / 'firmware/src/app/ui.c').read_text()
order_helpers = 'enum { PART_909=0, PART_808=1, PART_303A=2, PART_303B=3, PART_BRK=4 };\n'
order_helpers += re.search(r'^static const uint8_t PART_ORDER.*?;', ui_source, re.M)[0] + '\n'
order_helpers += re.search(r'^static int part_at\(.*', ui_source, re.M)[0] + '\n'
harness = r'''
#include <assert.h>
#include <stdint.h>
enum { R_ENG, T_MIX, T_FX, T_MST, MX_LEVEL, FX_RV_LEVEL, FX_DL_LEVEL,
       FX_VOLUME, MST_DJF, V_FX, V_MIX, V_HOME, V_GLO, V_PART, V_SEQ, O_NONE, NDRUM = 11, NPARTS = 5 };
typedef struct { int kind, a, b, c; } pref_t;
#define PR(k,a,b,c) ((pref_t){k,a,b,c})
static struct { int rec, part, view, overlay, help, sel[2]; } ui;
static struct { int rec_part, solo,locked,lock_kit,lock_bank; uint16_t drum_solo[2]; uint8_t fx_down; } smc;
static struct { int playing; } seq;
static int volume, filter;
static int pref_get(pref_t r) { return r.a == T_MST ? filter : volume; }
static int part_muted(int p) { (void)p; return 0; }
#define track_muted(k,t) ((void)(k),(void)(t),0)
static int smk_clip_mode_on(void) { return 0; }
#define is_drum() (ui.part < 2)
static int drum_mix_page(void) { return -1; }
static int cur_page(void) { return 0; }
static int smc_beat_lit(void) { return 1; } /* This fixture checks master mute, not beat timing. */
'''
harness += order_helpers + "\n".join(functions)
harness += r'''
int main(void) {
    const int expected[5]={0,1,4,3,2};
    for (int i = 0; i < 5; i++) {
        pref_t r = smc_home_target(i);
        assert(r.a == T_MIX && r.b == expected[i] && r.c == MX_LEVEL);
    }
    assert(smc_home_target(5).c == FX_RV_LEVEL);
    assert(smc_home_target(6).c == FX_DL_LEVEL);
    pref_t r = smc_home_target(7);
    assert(r.a == T_MST && r.c == MST_DJF);
    volume = 100; filter = 0;
    assert(!smc_led(23)); /* Filter endpoint must not light the master mute. */
    volume = 0; filter = 64;
    assert(smc_led(23));
    return 0;
}
'''
with tempfile.TemporaryDirectory() as tmp:
    c = Path(tmp) / "test.c"
    exe = Path(tmp) / "test"
    c.write_text(harness)
    subprocess.run([os.environ.get("CC", "cc"), "-std=c99", "-Wall", "-Wextra", "-Werror", str(c), "-o", str(exe)], check=True)
    subprocess.run([str(exe)], check=True)
print("PASS: SMC filter destination and independent master mute light")

